 "Показывать меня в рейтинге": "Show me in the ranking",
 "Рейтинг по минутам тренировок в приложении. Обновляется раз в несколько минут.": "Ranked by training minutes in the app. Updates every few minutes.",
 "Укажи город в профиле — и увидишь рейтинг своего города.": "Add your city to your profile to see your city's ranking.",
 "Рейтинг не загрузился. Проверь интернет.": "The ranking didn't load. Check your internet.",
