 "Твоё место появится через пару минут.": "Your place will show up in a couple of minutes.",
 "Пока в рейтинге никого нет — стань первым!": "No one in the ranking yet — be the first!",
 "Посмотри любой урок хотя бы минуту — и появишься в рейтинге.": "Watch any lesson for at least a minute to appear in the ranking.",
 "Консультация": "Consultation",
 "за 1 вопрос": "per question",
 "Отвечу на твой вопрос о брейкинге текстом в мессенджере.": "I'll answer your question about breaking in a text message.",
 "Задай любой вопрос о брейкинге — я лично отвечу текстом в мессенджере.": "Ask any question about breaking — I'll personally answer in a text message.",
 "Хочешь, чтобы я вёл тебя постоянно? Посмотри онлайн-ведение.": "Want me to coach you on an ongoing basis? Check out online coaching.",
 "Индивидуальная работа с тренером по переписке: разбор твоих видео, задания и план тренировок.": "One-on-one work with a coach over messenger: breakdowns of your videos, tasks and a training plan.",
 "Федоскин": "Fedosk1n",
 "Тренер по брейкингу, автор уроков в приложении": "Breaking coach, author of the lessons in this app",
 "лет в брейкинге": "years in breaking",
 "лет тренирую": "years coaching",
 "стран — онлайн-ученики": "countries with online students",
 "Не уверен, что нужно ведение? Начни с консультации: пришли видео — разберу его по кадрам.": "Not sure you need ongoing coaching? Start with a consultation: send a video and I'll break it down frame by frame.",
 "Напиши тренеру": "Message the coach",
 "Выбери услугу и мессенджер — сообщение уже будет написано.": "Pick a service and a messenger — the message will already be written.",
 "Обсуждаем задачу": "We discuss your goal",
 "Расскажи, что уже умеешь и чего хочешь добиться. Это бесплатно.": "Tell me what you can already do and what you want to achieve. This is free.",
 "Оплата": "Payment",
 "Реквизиты пришлю в чате.": "I'll send the payment details in the chat.",
 "Способ оплаты обсудим в чате. Можно оплатить криптой (USDT).": "We'll agree on the payment method in the chat. Crypto (USDT) is also accepted.",
 "Способ оплаты обсудим в чате.": "We'll agree on the payment method in the chat.",
 "Старт": "Start",
 "Ответ или первое задание — в течение {h} часов.": "You get the answer or your first task within {h} hours.",
 "Отвечаю раз в день, с {a} до {b} по твоему времени.": "I reply once a day, between {a} and {b} your time.",
 "Переписка — на твоём языке.": "We chat in your language.",
 "Рекомендую": "Recommended",
 "Пришли видео — разберу его по кадрам: скриншоты ключевых моментов и что исправить.": "Send a video and I'll break it down frame by frame: screenshots of the key moments and what to fix.",
 "Присылаешь видео элемента или перехода. Я лично разбираю его и отвечаю текстом.": "You send a video of a move or transition. I break it down personally and reply in text.",
 "Скриншоты ключевых моментов твоего видео.": "Screenshots of the key moments of your video.",
 "На каждом — где должны быть ноги, руки и корпус и зачем.": "On each one: where your legs, arms and body should be, and why.",
 "С чего начать исправлять.": "Where to start fixing.",
 "Я смотрю видео и даю задания раз в день, с {a} до {b} по твоему времени. Иногда отвечаю и в другое время.": "I review videos and give tasks once a day, between {a} and {b} your time. Sometimes I reply at other times too.",
 "Оплата — после того, как обсудим задачу.": "Payment comes after we discuss your goal.",
 "Разово разобрать элемент": "One-time breakdown of a move",
 "Стабильный прогресс по одному элементу": "Steady progress on one move",
 "Максимум внимания: план, питание, личные тренировки": "Maximum attention: plan, nutrition, private sessions",
 "Я думаю за тебя: план под тебя, питание, ежедневная коррекция и 8 тренировок один на один. Количество элементов не ограничено.": "I do the thinking for you: a plan made for you, nutrition, daily adjustments and 8 one-on-one sessions. No limit on the number of moves.",
 "любое количество элементов — без ограничений;": "any number of moves — no limit;",
 "Подготовка к крупным соревнованиям": "Preparing for major competitions",
 "Отлично подходит для подготовки к крупным соревнованиям: полное сопровождение до выхода на батл.": "A great fit for preparing for major competitions: full support all the way to stepping into the battle.",
 "ежедневная коррекция тренировок: устал, заболел, перетрудился.": "daily training adjustments: tired, sick, overtrained.",
 "Я думаю за тебя: план под тебя, питание и ежедневная коррекция тренировок. Количество элементов не ограничено.": "I do the thinking for you: a plan made for you, nutrition and daily adjustments to your training. No limit on the number of moves.",
 "разбор, коррекция и помощь в составлении раундов на батл;": "breakdown, correction and help building your battle rounds;",
 "Я составляю план и веду тебя каждый день: что, как, когда и зачем тренировать.": "I build your plan and guide you every day: what, how, when and why to train.",
 "В течение месяца ты получаешь мой опыт и знания. Это экономит время и снижает риск травм.": "For a month you get my experience and knowledge. This saves time and lowers the risk of injury.",
 "Подходит тем, кто готов тренироваться регулярно и выполнять задания.": "Suits those who are ready to train regularly and complete the tasks.",
