 "Ни разу не платил криптой?": "¿Nunca has pagado con cripto?",
 "Проще всего — через криптобиржу: Binance, Bybit, OKX, из США — Kraken. Нужна регистрация и проверка личности: обычно от 10 минут до суток.": "Lo más fácil es un exchange: Binance, Bybit, OKX o, desde EE. UU., Kraken. Hay que registrarse y verificar tu identidad: normalmente de 10 minutos a un día.",
 "USDT покупается там же банковской картой — раздел «Купить крипту» (Buy crypto).": "Puedes comprar USDT ahí mismo con tarjeta bancaria: busca «Comprar cripto» (Buy crypto).",
 "Coinbase, PayPal и Cash App не отправляют USDT в сети TRON — через них не получится.": "Coinbase, PayPal y Cash App no envían USDT por la red TRON: con ellos no funciona.",
