 "Задай любой вопрос о брейкинге — я лично отвечу текстом в мессенджере.": "Haz cualquier pregunta sobre breaking: te respondo personalmente por mensaje.",
 "Хочешь, чтобы я вёл тебя постоянно? Посмотри онлайн-ведение.": "¿Quieres que te entrene de forma continua? Mira el entrenamiento online.",
