 "Присылаешь видео элемента или перехода. Я лично разбираю его и отвечаю текстом.": "Envías un video de un paso o transición. Lo analizo personalmente y respondo por escrito.",
 "Скриншоты ключевых моментов твоего видео.": "Capturas de los momentos clave de tu video.",
