 "С чего начать исправлять.": "Por dónde empezar a corregir.",
 "Я смотрю видео и даю задания раз в день, с {a} до {b} по твоему времени. Иногда отвечаю и в другое время.": "Reviso videos y doy tareas una vez al día, entre las {a} y las {b} de tu hora. A veces respondo también en otros momentos.",
 "Оплата — после того, как обсудим задачу.": "El pago va después de hablar de tu objetivo.",
 "Разово разобрать элемент": "Analizar un paso una vez",
 "Стабильный прогресс по одному элементу": "Progreso constante en un paso",
 "Максимум внимания: план, питание, личные тренировки": "Máxima atención: plan, nutrición, sesiones privadas",
 "Я думаю за тебя: план под тебя, питание, ежедневная коррекция и 8 тренировок один на один. Количество элементов не ограничено.": "Yo pienso por ti: un plan hecho para ti, nutrición, ajustes diarios y 8 sesiones individuales. Sin límite de pasos.",
 "любое количество элементов — без ограничений;": "cualquier número de pasos, sin límite;",
 "Подготовка к крупным соревнованиям": "Preparación para grandes competiciones",
 "Отлично подходит для подготовки к крупным соревнованиям: полное сопровождение до выхода на батл.": "Ideal para prepararte para grandes competiciones: acompañamiento completo hasta que sales a la batalla.",
 "ежедневная коррекция тренировок: устал, заболел, перетрудился.": "ajustes diarios: cansancio, enfermedad, sobreentrenamiento.",
 "Я думаю за тебя: план под тебя, питание и ежедневная коррекция тренировок. Количество элементов не ограничено.": "Yo pienso por ti: un plan hecho para ti, nutrición y ajustes diarios del entrenamiento. Sin límite de pasos.",
 "разбор, коррекция и помощь в составлении раундов на батл;": "análisis, corrección y ayuda para armar tus rondas de batalla;",
 "Я составляю план и веду тебя каждый день: что, как, когда и зачем тренировать.": "Armo tu plan y te guío cada día: qué, cómo, cuándo y por qué entrenar.",
 "В течение месяца ты получаешь мой опыт и знания. Это экономит время и снижает риск травм.": "Durante un mes recibes mi experiencia y conocimientos. Esto ahorra tiempo y reduce el riesgo de lesiones.",
