 "Только USDT и только сеть TRON (TRC-20). С другой монетой или сетью деньги не дойдут, и вернуть их нельзя.": "Só USDT e só a rede TRON (TRC-20). Com outra moeda ou rede, o dinheiro não chega e não dá para recuperar.",
 "Ни разу не платил криптой?": "Nunca pagou com cripto?",
 "Проще всего — через криптобиржу: Binance, Bybit, OKX, из США — Kraken. Нужна регистрация и проверка личности: обычно от 10 минут до суток.": "O mais fácil é uma corretora de cripto: Binance, Bybit, OKX ou, nos EUA, Kraken. É preciso se cadastrar e verificar a identidade — normalmente de 10 minutos a um dia.",
 "USDT покупается там же банковской картой — раздел «Купить крипту» (Buy crypto).": "Dá para comprar USDT ali mesmo com cartão — procure “Comprar cripto” (Buy crypto).",
 "Coinbase, PayPal и Cash App не отправляют USDT в сети TRON — через них не получится.": "Coinbase, PayPal e Cash App não enviam USDT pela rede TRON — com eles não dá.",
 "Свой кошелёк (Trust Wallet, TronLink): кроме USDT нужно немного TRX — им платится комиссия сети. Без TRX перевод не пройдёт.": "Carteira própria (Trust Wallet, TronLink): além de USDT, você precisa de um pouco de TRX para a taxa da rede. Sem TRX a transferência não sai.",
 "Что-то непонятно? Напиши тренеру — помогу разобраться.": "Ficou alguma dúvida? Fale com o coach — eu te ajudo.",
 "Задать вопрос тренеру": "Perguntar ao coach",
