 "Я оплатил — отправить скриншот": "Já paguei — mandar o print",
 "Оплатил {amt} USDT (TRC-20) за: {svc}. Прикрепляю скриншот перевода.": "Paguei {amt} USDT (TRC-20) por: {svc}. Envio o print da transferência.",
