 "Биржа (Binance, Bybit, OKX, Kraken) или кошелёк → «Вывод» или «Отправить» → USDT.": "Une plateforme (Binance, Bybit, OKX, Kraken) ou un portefeuille → « Retirer » ou « Envoyer » → USDT.",
