 "Отправь и сделай скриншот": "Envoie et fais une capture d’écran",
 "Перевод приходит за 1–3 минуты. Вернись сюда и нажми кнопку ниже — пришли скриншот тренеру.": "Le virement arrive en 1 à 3 minutes. Reviens ici et appuie sur le bouton ci-dessous — envoie la capture au coach.",
 "Только USDT и только сеть TRON (TRC-20). С другой монетой или сетью деньги не дойдут, и вернуть их нельзя.": "Uniquement de l’USDT et uniquement le réseau TRON (TRC-20). Avec une autre crypto ou un autre réseau, l’argent n’arrive pas et ne peut pas être récupéré.",
 "Ни разу не платил криптой?": "Jamais payé en crypto ?",
 "Проще всего — через криптобиржу: Binance, Bybit, OKX, из США — Kraken. Нужна регистрация и проверка личности: обычно от 10 минут до суток.": "Le plus simple : une plateforme crypto — Binance, Bybit, OKX, ou Kraken depuis les États-Unis. Il faut s’inscrire et vérifier ton identité : en général de 10 minutes à une journée.",
 "USDT покупается там же банковской картой — раздел «Купить крипту» (Buy crypto).": "Tu peux acheter des USDT sur place avec une carte bancaire — cherche « Acheter de la crypto » (Buy crypto).",
 "Coinbase, PayPal и Cash App не отправляют USDT в сети TRON — через них не получится.": "Coinbase, PayPal et Cash App n’envoient pas d’USDT sur le réseau TRON — ça ne marchera pas avec eux.",
 "Свой кошелёк (Trust Wallet, TronLink): кроме USDT нужно немного TRX — им платится комиссия сети. Без TRX перевод не пройдёт.": "Ton propre portefeuille (Trust Wallet, TronLink) : en plus des USDT, il te faut un peu de TRX pour les frais de réseau. Sans TRX, le virement ne passe pas.",
