 "Рейтинг по минутам тренировок в приложении. Обновляется раз в несколько минут.": "Classement par minutes d'entraînement dans l'app. Mis à jour toutes les quelques minutes.",
 "Укажи город в профиле — и увидишь рейтинг своего города.": "Ajoute ta ville dans le profil pour voir le classement de ta ville.",
 "Рейтинг не загрузился. Проверь интернет.": "Le classement ne s'est pas chargé. Vérifie ta connexion.",
