 "Пока в рейтинге никого нет — стань первым!": "Personne dans le classement pour l'instant : sois le premier !",
 "Посмотри любой урок хотя бы минуту — и появишься в рейтинге.": "Regarde n'importe quelle leçon au moins une minute pour apparaître dans le classement.",
 "Консультация": "Consultation",
 "за 1 вопрос": "par question",
 "Отвечу на твой вопрос о брейкинге текстом в мессенджере.": "Je réponds à ta question sur le breaking par message.",
 "Задай любой вопрос о брейкинге — я лично отвечу текстом в мессенджере.": "Pose n'importe quelle question sur le breaking : je te réponds moi-même par message.",
 "Хочешь, чтобы я вёл тебя постоянно? Посмотри онлайн-ведение.": "Tu veux que je te coache en continu ? Regarde le coaching en ligne.",
 "Индивидуальная работа с тренером по переписке: разбор твоих видео, задания и план тренировок.": "Travail individuel avec un coach par messagerie : analyse de tes vidéos, exercices et plan d'entraînement.",
 "Федоскин": "Fedosk1n",
 "Тренер по брейкингу, автор уроков в приложении": "Coach de breaking, auteur des leçons de l'app",
 "лет в брейкинге": "ans de breaking",
 "лет тренирую": "ans de coaching",
 "стран — онлайн-ученики": "pays d'élèves en ligne",
 "Не уверен, что нужно ведение? Начни с консультации: пришли видео — разберу его по кадрам.": "Pas sûr d'avoir besoin d'un suivi ? Commence par une consultation : envoie une vidéo, je l'analyse image par image.",
 "Напиши тренеру": "Écris au coach",
 "Выбери услугу и мессенджер — сообщение уже будет написано.": "Choisis un service et une messagerie : le message sera déjà écrit.",
 "Обсуждаем задачу": "On parle de ton objectif",
 "Расскажи, что уже умеешь и чего хочешь добиться. Это бесплатно.": "Dis-moi ce que tu sais déjà faire et ce que tu veux atteindre. C'est gratuit.",
 "Оплата": "Paiement",
 "Реквизиты пришлю в чате.": "Je t'envoie les infos de paiement dans le chat.",
 "Способ оплаты обсудим в чате. Можно оплатить криптой (USDT).": "On choisit le moyen de paiement dans le chat. La crypto (USDT) est aussi acceptée.",
 "Способ оплаты обсудим в чате.": "On choisit le moyen de paiement dans le chat.",
 "Старт": "Début",
 "Ответ или первое задание — в течение {h} часов.": "Tu reçois la réponse ou ton premier exercice sous {h} heures.",
 "Отвечаю раз в день, с {a} до {b} по твоему времени.": "Je réponds une fois par jour, entre {a} et {b} à ton heure.",
 "Переписка — на твоём языке.": "On échange dans ta langue.",
 "Рекомендую": "Recommandé",
 "Пришли видео — разберу его по кадрам: скриншоты ключевых моментов и что исправить.": "Envoie une vidéo, je l'analyse image par image : captures des moments clés et ce qu'il faut corriger.",
 "Присылаешь видео элемента или перехода. Я лично разбираю его и отвечаю текстом.": "Tu envoies une vidéo d'un move ou d'une transition. Je l'analyse moi-même et je réponds par écrit.",
 "Скриншоты ключевых моментов твоего видео.": "Des captures des moments clés de ta vidéo.",
 "На каждом — где должны быть ноги, руки и корпус и зачем.": "Sur chacune : où doivent être les jambes, les bras et le buste, et pourquoi.",
 "С чего начать исправлять.": "Par où commencer à corriger.",
 "Я смотрю видео и даю задания раз в день, с {a} до {b} по твоему времени. Иногда отвечаю и в другое время.": "Je regarde les vidéos et donne les exercices une fois par jour, entre {a} et {b} à ton heure. Parfois je réponds aussi à d'autres moments.",
 "Оплата — после того, как обсудим задачу.": "Le paiement vient après avoir parlé de ton objectif.",
 "Разово разобрать элемент": "Analyse ponctuelle d'un move",
 "Стабильный прогресс по одному элементу": "Progrès régulier sur un move",
 "Максимум внимания: план, питание, личные тренировки": "Attention maximale : plan, nutrition, séances privées",
 "Я думаю за тебя: план под тебя, питание, ежедневная коррекция и 8 тренировок один на один. Количество элементов не ограничено.": "Je réfléchis à ta place : un plan fait pour toi, nutrition, ajustements quotidiens et 8 séances en tête-à-tête. Nombre de moves illimité.",
 "любое количество элементов — без ограничений;": "autant de moves que tu veux, sans limite ;",
 "Подготовка к крупным соревнованиям": "Préparation aux grandes compétitions",
 "Отлично подходит для подготовки к крупным соревнованиям: полное сопровождение до выхода на батл.": "Idéal pour préparer les grandes compétitions : un accompagnement complet jusqu'à ton entrée dans la battle.",
 "ежедневная коррекция тренировок: устал, заболел, перетрудился.": "ajustements quotidiens : fatigue, maladie, surentraînement.",
 "Я думаю за тебя: план под тебя, питание и ежедневная коррекция тренировок. Количество элементов не ограничено.": "Je réfléchis à ta place : un plan fait pour toi, la nutrition et des ajustements quotidiens de l'entraînement. Nombre de moves illimité.",
 "разбор, коррекция и помощь в составлении раундов на батл;": "analyse, correction et aide pour construire tes passages de battle ;",
 "Я составляю план и веду тебя каждый день: что, как, когда и зачем тренировать.": "Je construis ton plan et je te guide chaque jour : quoi, comment, quand et pourquoi t'entraîner.",
 "В течение месяца ты получаешь мой опыт и знания. Это экономит время и снижает риск травм.": "Pendant un mois, tu profites de mon expérience et de mes connaissances. Cela fait gagner du temps et réduit le risque de blessure.",
 "Подходит тем, кто готов тренироваться регулярно и выполнять задания.": "Pour ceux qui sont prêts à s'entraîner régulièrement et à faire les exercices.",
