 "Он появится в приложении после проверки.": "Il apparaîtra dans l'app après vérification.",
 "По этой ссылке отзыв уже оставлен. Спасибо!": "Un avis a déjà été laissé avec ce lien. Merci !",
 "Нет связи с сервером. Проверь интернет и открой ссылку ещё раз.": "Impossible de joindre le serveur. Vérifie ta connexion et rouvre le lien.",
