 "Чат в приложении": "Chat dans l'app",
 "ответ придёт сюда": "la réponse arrive ici",
 "Не отправлено — нажми, чтобы повторить": "Non envoyé — touche pour réessayer",
 "Отправляется…": "Envoi…",
 "Расскажи, что умеешь и чего хочешь добиться. Можно сразу прикрепить видео элемента — Федоскин ответит лично здесь же.": "Dis-moi ce que tu sais faire et ce que tu veux atteindre. Tu peux joindre tout de suite une vidéo de ton move — Fedosk1n te répondra lui-même ici.",
 "Чтобы ответ тренера приходил уведомлением, добавь приложение на экран «Домой».": "Pour recevoir la réponse en notification, ajoute l'app à ton écran d'accueil.",
 "Как добавить": "Comment l'ajouter",
