 "Замедление, зеркало и «Цикл 3 сек» помогут разобрать движение: «Цикл 3 сек» крутит по кругу момент, на котором стоит видео, «Повтор» — весь урок.": "Le ralenti, le miroir et « Boucle 3 s » aident à décortiquer le mouvement : « Boucle 3 s » rejoue le moment où en est la vidéo, « Répéter » toute la leçon.",
