 "Память на телефоне": "Stockage",
 "Уроки, которые ты смотрел, хранятся на телефоне: второй раз они открываются сразу и без интернета. Когда место заканчивается, самые старые удаляются сами.": "Les leçons que tu as regardées sont gardées sur ton téléphone : la prochaine fois, elles s’ouvrent tout de suite, même sans internet. Quand l’espace est plein, les plus anciennes sont supprimées automatiquement.",
 "На iPhone и iPad приложение не хранит видео — место на телефоне они не занимают.": "Sur iPhone et iPad, l’app ne garde pas les vidéos : elles ne prennent pas de place sur ton appareil.",
