 "Замедление, зеркало и повтор 3 сек помогут разобрать движение. Повтор зацикливает момент, на котором стоит видео.": "Zeitlupe, Spiegeln und 3-Sekunden-Loop helfen dir, den Move zu verstehen. Der Loop wiederholt die aktuelle Stelle im Video.",
