 "Важно:": "Wichtig:",
 "Как оплатить": "So bezahlst du",
 "Открой приложение, где есть USDT": "Öffne die App, in der du USDT hast",
 "Биржа (Binance, Bybit, OKX, Kraken) или кошелёк → «Вывод» или «Отправить» → USDT.": "Eine Börse (Binance, Bybit, OKX, Kraken) oder ein Wallet → „Auszahlen“ oder „Senden“ → USDT.",
 "Выбери сеть TRON (TRC-20)": "Wähle das Netzwerk TRON (TRC-20)",
 "В приложении она может называться «TRX» или «Tron». Другая сеть — деньги не дойдут.": "In der App heißt es vielleicht „TRX“ oder „Tron“. Ein anderes Netzwerk — das Geld kommt nicht an.",
 "Вставь адрес": "Füge die Adresse ein",
 "Показать QR-код (если кошелёк на другом устройстве)": "QR-Code zeigen (wenn dein Wallet auf einem anderen Gerät ist)",
 "Скрыть QR-код": "QR-Code ausblenden",
 "Проверь сумму": "Prüfe den Betrag",
 "Перед отправкой посмотри строку «Получите» (Receive amount): там должно быть {amt} USDT. Если меньше — прибавь комиссию биржи (обычно около 1 USDT).": "Schau vor dem Senden auf „Erhaltener Betrag“ (Receive amount): Dort müssen {amt} USDT stehen. Ist es weniger, rechne die Gebühr der Börse dazu (meist etwa 1 USDT).",
 "Отправь и сделай скриншот": "Senden und Screenshot machen",
 "Перевод приходит за 1–3 минуты. Вернись сюда и нажми кнопку ниже — пришли скриншот тренеру.": "Die Zahlung kommt in 1–3 Minuten an. Komm hierher zurück und tippe unten auf den Button — schick den Screenshot an den Coach.",
 "Только USDT и только сеть TRON (TRC-20). С другой монетой или сетью деньги не дойдут, и вернуть их нельзя.": "Nur USDT und nur das TRON-Netzwerk (TRC-20). Mit anderen Coins oder Netzwerken kommt das Geld nicht an und ist verloren.",
 "Ни разу не платил криптой?": "Noch nie mit Krypto bezahlt?",
 "Проще всего — через криптобиржу: Binance, Bybit, OKX, из США — Kraken. Нужна регистрация и проверка личности: обычно от 10 минут до суток.": "Am einfachsten über eine Kryptobörse: Binance, Bybit, OKX, aus den USA Kraken. Du brauchst ein Konto und eine Identitätsprüfung — meist 10 Minuten bis ein Tag.",
 "USDT покупается там же банковской картой — раздел «Купить крипту» (Buy crypto).": "USDT kannst du dort direkt mit Bankkarte kaufen — such nach „Krypto kaufen“ (Buy crypto).",
 "Coinbase, PayPal и Cash App не отправляют USDT в сети TRON — через них не получится.": "Coinbase, PayPal und Cash App können kein USDT über TRON senden — damit klappt es nicht.",
 "Свой кошелёк (Trust Wallet, TronLink): кроме USDT нужно немного TRX — им платится комиссия сети. Без TRX перевод не пройдёт.": "Eigenes Wallet (Trust Wallet, TronLink): Neben USDT brauchst du etwas TRX für die Netzwerkgebühr. Ohne TRX geht die Zahlung nicht raus.",
 "Что-то непонятно? Напиши тренеру — помогу разобраться.": "Etwas unklar? Schreib dem Coach — ich helfe dir.",
