 "Покажем только имя. Фамилию писать не обязательно.": "Nur dein Vorname wird angezeigt. Der Nachname ist nicht nötig.",
 "Отзыв": "Bewertung",
 "Что получилось за время занятий? Что изменилось?": "Was hast du im Training erreicht? Was hat sich verändert?",
 "Отправить отзыв": "Bewertung senden",
 "Отправляю…": "Wird gesendet…",
 "Спасибо! Отзыв отправлен тренеру.": "Danke! Deine Bewertung wurde an den Coach gesendet.",
 "Он появится в приложении после проверки.": "Sie erscheint nach einer Prüfung in der App.",
 "По этой ссылке отзыв уже оставлен. Спасибо!": "Mit diesem Link wurde schon eine Bewertung abgegeben. Danke!",
 "Нет связи с сервером. Проверь интернет и открой ссылку ещё раз.": "Keine Verbindung zum Server. Prüfe das Internet und öffne den Link erneut.",
 "Ссылка недействительна. Попроси тренера прислать новую.": "Der Link ist ungültig. Bitte den Coach um einen neuen.",
 "Отзыв увидят другие ученики в приложении.": "Andere Schüler sehen deine Bewertung in der App.",
 "Поставь оценку — нажми на звёзды.": "Gib eine Bewertung ab – tippe auf die Sterne.",
 "Напиши своё имя.": "Gib deinen Namen ein.",
 "Напиши хотя бы пару предложений.": "Schreib mindestens ein paar Sätze.",
 "Не получилось отправить. Проверь интернет и попробуй ещё раз.": "Senden fehlgeschlagen. Prüfe das Internet und versuch es noch mal.",
 "Чат с тренером": "Chat mit dem Coach",
 "Написать в чат": "Im Chat schreiben",
 "Отвечает лично": "Antwortet persönlich",
 "Как тебя зовут?": "Wie heißt du?",
 "Сообщение…": "Nachricht…",
 "Фото или видео": "Foto oder Video",
 "Чат в приложении": "Chat in der App",
 "ответ придёт сюда": "die Antwort kommt hierher",
 "Не отправлено — нажми, чтобы повторить": "Nicht gesendet – tippen zum Wiederholen",
 "Отправляется…": "Wird gesendet…",
 "Расскажи, что умеешь и чего хочешь добиться. Можно сразу прикрепить видео элемента — Федоскин ответит лично здесь же.": "Erzähl, was du kannst und was du erreichen willst. Du kannst gleich ein Video deines Moves anhängen – Fedosk1n antwortet persönlich hier.",
 "Чтобы ответ тренера приходил уведомлением, добавь приложение на экран «Домой».": "Damit die Antwort als Mitteilung kommt, füge die App zum Home-Bildschirm hinzu.",
 "Как добавить": "So geht's",
 "Включи уведомления, чтобы не пропустить ответ тренера.": "Schalte Mitteilungen ein, damit du die Antwort nicht verpasst.",
 "Напиши, как тебя зовут": "Gib deinen Namen ein",
 "Слишком много сообщений подряд — подожди немного": "Zu viele Nachrichten hintereinander – warte kurz",
 "Файл слишком большой — до 95 МБ. Обрежь видео или сними короче.": "Die Datei ist zu groß – bis 95 MB. Kürze das Video oder filme kürzer.",
 "Можно отправить только фото или видео": "Nur Fotos oder Videos möglich",
