 "+ Добавить имя": "+ Namen hinzufügen",
 "Замедление, зеркало и «Цикл 3 сек» помогут разобрать движение: «Цикл 3 сек» крутит по кругу момент, на котором стоит видео, «Повтор» — весь урок.": "Zeitlupe, Spiegel und „Loop 3 s“ helfen, die Bewegung zu verstehen: „Loop 3 s“ wiederholt die aktuelle Stelle, „Wiederholen“ die ganze Lektion.",
 "Загрузка {p} %": "Lädt {p} %",
 "Сохранён на телефоне": "Auf deinem Handy gespeichert",
 "Загружен целиком": "Vollständig geladen",
 "Память на телефоне": "Speicher",
 "Уроки, которые ты смотрел, хранятся на телефоне: второй раз они открываются сразу и без интернета. Когда место заканчивается, самые старые удаляются сами.": "Lektionen, die du angesehen hast, bleiben auf deinem Handy: Beim nächsten Mal öffnen sie sofort, auch ohne Internet. Wenn der Platz voll ist, werden die ältesten automatisch gelöscht.",
