 "Перевод приходит за 1–3 минуты. Вернись сюда и нажми кнопку ниже — пришли скриншот тренеру.": "送金は1〜3分で届きます。ここに戻って下のボタンを押し、スクリーンショットをコーチに送ってください。",
 "Только USDT и только сеть TRON (TRC-20). С другой монетой или сетью деньги не дойдут, и вернуть их нельзя.": "USDTのみ、ネットワークはTRON（TRC-20）のみ。ほかの通貨やネットワークだと届かず、取り戻せません。",
 "Ни разу не платил криптой?": "暗号資産で払うのは初めて？",
 "Проще всего — через криптобиржу: Binance, Bybit, OKX, из США — Kraken. Нужна регистрация и проверка личности: обычно от 10 минут до суток.": "いちばん簡単なのは暗号資産取引所：Binance、Bybit、OKX、アメリカならKraken。登録と本人確認が必要で、通常10分〜1日かかります。",
 "USDT покупается там же банковской картой — раздел «Купить крипту» (Buy crypto).": "USDTはそのアプリで銀行カードを使って買えます。「暗号資産を購入」（Buy crypto）を探してください。",
 "Coinbase, PayPal и Cash App не отправляют USDT в сети TRON — через них не получится.": "Coinbase、PayPal、Cash AppはTRONネットワークでUSDTを送れないため、使えません。",
