 "Покажем только имя. Фамилию писать не обязательно.": "表示されるのは名前だけです。名字は不要です。",
 "Отзыв": "レビュー",
 "Что получилось за время занятий? Что изменилось?": "練習で何ができるようになった？何が変わった？",
 "Отправить отзыв": "レビューを送信",
