 "Он появится в приложении после проверки.": "確認後、アプリに表示されます。",
 "По этой ссылке отзыв уже оставлен. Спасибо!": "このリンクではすでにレビューが投稿されています。ありがとう！",
 "Нет связи с сервером. Проверь интернет и открой ссылку ещё раз.": "サーバーに接続できません。ネット接続を確認して、もう一度リンクを開いてください。",
 "Ссылка недействительна. Попроси тренера прислать новую.": "このリンクは無効です。コーチに新しいリンクを頼んでください。",
