 "Рейтинг по минутам тренировок в приложении. Обновляется раз в несколько минут.": "按应用内训练分钟数排名，每几分钟更新一次。",
 "Укажи город в профиле — и увидишь рейтинг своего города.": "在个人资料里填写城市，就能看到你所在城市的排行榜。",
