 "Посмотри любой урок хотя бы минуту — и появишься в рейтинге.": "观看任意课程至少一分钟，就会出现在排行榜上。",
 "Консультация": "咨询",
 "за 1 вопрос": "每个问题",
 "Отвечу на твой вопрос о брейкинге текстом в мессенджере.": "我会用文字消息回答你关于霹雳舞的问题。",
 "Задай любой вопрос о брейкинге — я лично отвечу текстом в мессенджере.": "关于霹雳舞，问什么都可以——我会亲自用文字消息回答。",
 "Хочешь, чтобы я вёл тебя постоянно? Посмотри онлайн-ведение.": "想让我长期指导你？看看线上指导。",
 "Индивидуальная работа с тренером по переписке: разбор твоих видео, задания и план тренировок.": "通过聊天应用与教练一对一：分析你的视频、布置任务、制定训练计划。",
 "Федоскин": "Fedosk1n",
 "Тренер по брейкингу, автор уроков в приложении": "霹雳舞教练，应用内课程作者",
 "лет в брейкинге": "年霹雳舞经历",
 "лет тренирую": "年执教经历",
 "стран — онлайн-ученики": "个国家的线上学员",
 "Не уверен, что нужно ведение? Начни с консультации: пришли видео — разберу его по кадрам.": "不确定是否需要长期指导？先从咨询开始：发来视频，我逐帧分析。",
 "Напиши тренеру": "联系教练",
 "Выбери услугу и мессенджер — сообщение уже будет написано.": "选择服务和聊天应用，消息已经替你写好。",
 "Обсуждаем задачу": "沟通目标",
 "Расскажи, что уже умеешь и чего хочешь добиться. Это бесплатно.": "告诉我你现在会什么、想达到什么目标。这一步免费。",
 "Оплата": "付款",
 "Реквизиты пришлю в чате.": "付款信息我会在聊天中发给你。",
 "Способ оплаты обсудим в чате. Можно оплатить криптой (USDT).": "付款方式在聊天中商定，也可以用加密货币（USDT）支付。",
 "Способ оплаты обсудим в чате.": "付款方式在聊天中商定。",
 "Старт": "开始",
 "Ответ или первое задание — в течение {h} часов.": "{h} 小时内收到回复或第一个任务。",
 "Отвечаю раз в день, с {a} до {b} по твоему времени.": "我每天回复一次，你当地时间 {a}–{b}。",
 "Переписка — на твоём языке.": "用你的语言沟通。",
 "Рекомендую": "推荐",
 "Пришли видео — разберу его по кадрам: скриншоты ключевых моментов и что исправить.": "发来视频，我逐帧分析：关键时刻截图和需要纠正的地方。",
 "Присылаешь видео элемента или перехода. Я лично разбираю его и отвечаю текстом.": "你发来一个动作或衔接的视频，我亲自分析并用文字回复。",
 "Скриншоты ключевых моментов твоего видео.": "你视频中关键时刻的截图。",
 "На каждом — где должны быть ноги, руки и корпус и зачем.": "每张都标出腿、手臂和身体应该在哪里，以及为什么。",
 "С чего начать исправлять.": "从哪里开始纠正。",
 "Я смотрю видео и даю задания раз в день, с {a} до {b} по твоему времени. Иногда отвечаю и в другое время.": "我每天看一次视频并布置任务，你当地时间 {a}–{b}。有时也会在其他时间回复。",
 "Оплата — после того, как обсудим задачу.": "先沟通目标，再付款。",
 "Разово разобрать элемент": "单次分析一个动作",
 "Стабильный прогресс по одному элементу": "一个动作稳步进步",
 "Максимум внимания: план, питание, личные тренировки": "全方位关注：计划、营养、私教课",
 "Я думаю за тебя: план под тебя, питание, ежедневная коррекция и 8 тренировок один на один. Количество элементов не ограничено.": "我替你思考：专属计划、营养、每日调整和 8 次一对一课程。动作数量不限。",
 "любое количество элементов — без ограничений;": "动作数量不限；",
 "Подготовка к крупным соревнованиям": "备战大型比赛",
 "Отлично подходит для подготовки к крупным соревнованиям: полное сопровождение до выхода на батл.": "非常适合备战大型比赛：全程陪伴，直到你走上 battle 的那一刻。",
 "ежедневная коррекция тренировок: устал, заболел, перетрудился.": "每日调整训练：累了、病了、练过头了。",
 "Я думаю за тебя: план под тебя, питание и ежедневная коррекция тренировок. Количество элементов не ограничено.": "我替你思考：专属计划、营养和每日训练调整。动作数量不限。",
 "разбор, коррекция и помощь в составлении раундов на батл;": "分析、纠正并帮你编排 battle 回合；",
 "Я составляю план и веду тебя каждый день: что, как, когда и зачем тренировать.": "我为你制定计划并每天指导：练什么、怎么练、何时练、为什么练。",
 "В течение месяца ты получаешь мой опыт и знания. Это экономит время и снижает риск травм.": "一个月里你将获得我的经验和知识。这能节省时间并降低受伤风险。",
 "Подходит тем, кто готов тренироваться регулярно и выполнять задания.": "适合愿意规律训练并完成任务的人。",
